//! The native host bridge: while the testkit calls into a plugin it installs this backend so that
//! `host()` calls from the plugin land on the fakes of the `FakeHost` (manual: rust-sdk.md "Calling the
//! host", reference-test-harness.md "Fakes"). Calls the fakes do not model answer `unsupported`.
//! Generated by the SDK build helper from the host traits; edit the helpers, not the delegations.

use std::collections::BTreeMap;

use ilium_plugin_sdk_core::generated::host::*;
use ilium_plugin_sdk_core::generated::primitives::{AgentPane, HostAgent, SessionRef, SignatureSpec, TranscriptQuery, TranscriptTurn, TurnRole};
use ilium_plugin_sdk_core::generated::types::*;
use ilium_plugin_sdk_core::{clear_host, set_host, HostApi};

use ilium_plugin_sdk_core::exports::{HookCall, HookReply};

use super::{FakeHost, FakeTranscript};

/// Results of host calls that the plugin collects later with the matching `take-*` call.
#[derive(Debug, Default)]
pub(super) struct BridgeState {
    bytes: BTreeMap<u64, Vec<u8>>,
    http: BTreeMap<u64, HttpResponse>,
    completions: BTreeMap<u64, Completion>,
    exits: BTreeMap<u64, ProcessExit>,
    replies: BTreeMap<u64, String>,
    transcripts: BTreeMap<u64, Vec<TranscriptTurn>>,
    /// Topics the plugin published, as `(topic, payload JSON)` in publish order.
    pub(super) published: Vec<(String, String)>,
    /// Running timers as `(id, repeat)`.
    pub(super) timers: BTreeMap<u64, Option<u32>>,
    /// Durable timers as `name -> due epoch`.
    pub(super) durable: BTreeMap<String, u64>,
}

/// Keeps the bridge installed for one call into the plugin and removes it afterwards.
pub(super) struct BridgeGuard;

impl Drop for BridgeGuard {
    fn drop(&mut self) {
        clear_host();
    }
}

/// Installs the bridge for `host`. The caller must not use `host` until the guard is dropped and must
/// have moved the plugin out of it: the bridge reaches the fakes through a raw pointer for that span.
pub(super) fn enter(host: &mut FakeHost) -> BridgeGuard {
    let bridge = NativeBridge { host: host as *mut FakeHost };
    set_host(Box::new(Box::new(bridge) as Box<dyn HostApi>));
    BridgeGuard
}

struct NativeBridge {
    host: *mut FakeHost,
}

impl NativeBridge {
    fn host(&mut self) -> &mut FakeHost {
        // SAFETY: `enter` is only called with the plugin moved out of the host and the host untouched
        // until the guard drops; the pointer is cleared with the guard, so it is valid and unaliased
        // for every call the plugin makes in between.
        unsafe { &mut *self.host }
    }

    fn next_id(&mut self) -> u64 {
        self.host().jobs_next_request()
    }

    fn complete(&mut self, id: u64, outcome: Outcome) {
        let event = Event::RequestCompleted(RequestResult {
            request: RequestRef::Call(RequestId(id)),
            outcome,
        });
        self.host().outbox.borrow_mut().push(event);
    }

    fn permit(&mut self, grant: &str) -> Result<(), PluginError> {
        if self.host().granted.contains(grant) {
            return Ok(());
        }
        Err(PluginError::new(ErrorCode::NotPermitted, format!("the {grant} grant is missing")))
    }

    fn fs_permit(&mut self, base: &str, scope: &str) -> Result<(), PluginError> {
        let granted = &self.host().granted;
        if granted.contains(base) || granted.contains(&format!("{base}:{scope}")) {
            return Ok(());
        }
        Err(PluginError::new(ErrorCode::NotPermitted, format!("{base}:{scope} is not granted")))
    }

    /// An `http` grant covers everything; `http:<host>` one host; `http:*.<domain>` its subdomains only.
    fn http_permitted(&mut self, url: &str) -> bool {
        let rest = url.split_once("://").map_or(url, |(_, rest)| rest);
        let authority = rest.split(['/', '?', '#']).next().unwrap_or("");
        let host = authority.rsplit('@').next().unwrap_or("");
        let host = host.rsplit_once(':').map_or(host, |(name, _)| name).to_ascii_lowercase();
        self.host().granted.iter().any(|grant| {
            if grant == "http" {
                return true;
            }
            let Some(pattern) = grant.strip_prefix("http:") else {
                return false;
            };
            let pattern = pattern.to_ascii_lowercase();
            match pattern.strip_prefix("*.") {
                Some(domain) => host.len() > domain.len() + 1 && host.ends_with(&format!(".{domain}")),
                None => pattern == host,
            }
        })
    }

    fn cli_append(&mut self, invocation: u64, stderr: bool, text: &str) -> Result<(), PluginError> {
        if self.host().cli.append(invocation, stderr, text) {
            return Ok(());
        }
        Err(PluginError::new(ErrorCode::NotFound, format!("no command invocation {invocation} is running")))
    }
}

